# Let me try a different encoding - maybe Z3 was correct but let me double-check
# by trying a direct search using pysat or a different approach

# First, let me try to understand if there's a known solution.
# QG3: (x*y)*(y*x) = x
# Idempotent: x*x = x

# Let me try encoding as a SAT problem using pysat
from pysat.card import CardEnc
from pysat.solvers import Glucose3

n = 6

# We'll encode: for each cell (i,j), we have variables for each possible value v
# v_ij_k means x[i][j] = k

def idx(i, j, k):
    """Variable index for x[i][j] = k"""
    return i * n * n + j * n + k + 1

total_vars = n * n * n

clauses = []

# Each cell has at least one value
for i in range(n):
    for j in range(n):
        clause = [idx(i, j, k) for k in range(n)]
        clauses.append(clause)

# Each cell has at most one value (use pairwise encoding)
for i in range(n):
    for j in range(n):
        for k in range(n):
            for l in range(k+1, n):
                clauses.append([-idx(i, j, k), -idx(i, j, l)])

# Latin square: each row has each value exactly once
# For each row i and value k, exactly one column j has x[i][j]=k
for i in range(n):
    for k in range(n):
        clause = [idx(i, j, k) for j in range(n)]
        clauses.append(clause)
        # at most one: pairwise
        for j in range(n):
            for jj in range(j+1, n):
                clauses.append([-idx(i, j, k), -idx(i, jj, k)])

# Each column has each value exactly once
for j in range(n):
    for k in range(n):
        clause = [idx(i, j, k) for i in range(n)]
        clauses.append(clause)
        for i in range(n):
            for ii in range(i+1, n):
                clauses.append([-idx(i, j, k), -idx(ii, j, k)])

# Idempotent: x[i][i] = i
for i in range(n):
    clauses.append([idx(i, i, i)])

# QG3: x[ x[i][j] ][ x[j][i] ] = i
# For all i,j,a,b: if x[i][j]=a and x[j][i]=b then x[a][b]=i
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                # -(x[i][j]=a) or -(x[j][i]=b) or (x[a][b]=i)
                clauses.append([-idx(i, j, a), -idx(j, i, b), idx(a, b, i)])

print(f"Total variables: {total_vars}")
print(f"Total clauses: {len(clauses)}")

solver = Glucose3()
for c in clauses:
    solver.add_clause(c)

result = solver.solve()
print("Result:", result)

if result:
    model = solver.get_model()
    # Decode
    grid = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if model[idx(i, j, k)-1] > 0:
                    grid[i][j] = k
                    break
    print("Solution:")
    for row in grid:
        print(row)
    # Verify
    for i in range(n):
        assert len(set(grid[i])) == n
        assert len(set(grid[k][i] for k in range(n))) == n
        assert grid[i][i] == i
    for i in range(n):
        for j in range(n):
            a = grid[i][j]
            b = grid[j][i]
            assert grid[a][b] == i, f"Fail at {i},{j}: {a},{b} -> {grid[a][b]}"
    print("All checks passed!")
else:
    print("UNSAT")

